        for c in range(w-2):
            if all(g[r+i][c+j]==2 for i in (0,1) for j in (0,1)):
                ring={'TL':(r-1,c-1),'TR':(r-1,c+1),'BL':(r+1,c-1),'BR':(r+1,c+1)}
                rings.append((ring,(r,c)))
    def assign(cell):
        # owner = block whose marker-ring cell distance smallest; markers are diagonally adjacent so dist 1
